<?php
$audit=$wid?row('SELECT * FROM seo_audits WHERE website_id=? ORDER BY id DESC LIMIT 1',[$wid]):null;
$keywords=$wid?(int)value('SELECT COUNT(*) FROM keywords WHERE website_id=?',[$wid]):0;$issues=$audit?(int)value("SELECT COUNT(*) FROM seo_issues WHERE audit_id=? AND status='open'",[$audit['id']]):0;$done=$wid?(int)value("SELECT COUNT(*) FROM seo_tasks WHERE website_id=? AND status='completed'",[$wid]):0;
if($w):?><div class="welcome-banner"><div><h3>A healthier website starts with a clear next step.</h3><p>Review your latest audit, prioritize what matters, and keep moving forward.</p></div><a class="button" href="<?=url('/audit?website_id='.$wid)?>">View opportunities ↗</a></div><?php endif;?>
<div class="grid grid-4"><?php foreach([['SEO health score',$audit?$audit['score'].' / 100':'—','◎','Internal diagnostic score'],['Tracked keywords',number_format($keywords),'⌘','Across this project'],['Open SEO issues',$audit?number_format($issues):'—','⚑','From your most recent audit'],['Completed tasks',number_format($done),'☑','Progress you can build on']] as [$label,$val,$icon,$foot]):?><div class="card metric"><div class="metric-label"><?=e($label)?><span class="metric-icon"><?=e($icon)?></span></div><div class="metric-value"><?=e($val)?></div><div class="metric-foot"><?=e($foot)?></div></div><?php endforeach;?></div>
<div class="dashboard-grid"><div class="card"><div class="card-header"><div><h3>SEO health over time</h3><span class="small">Small improvements. Lasting momentum.</span></div><span class="badge">Last 12 audits</span></div><?php $trend=$wid?array_reverse(rows('SELECT score,created_at FROM seo_audits WHERE website_id=? ORDER BY id DESC LIMIT 12',[$wid])):[];if(count($trend)>1){$points=[];foreach($trend as $i=>$t)$points[]=(40+$i*620/max(1,count($trend)-1)).','.(190-$t['score']*1.6);?><svg class="chart" viewBox="0 0 700 225" role="img" aria-label="SEO health score across your recent audits"><path class="chart-grid" d="M40 30H670 M40 70H670 M40 110H670 M40 150H670 M40 190H670"/><text x="3" y="34">100</text><text x="10" y="113">50</text><text x="17" y="194">0</text><polyline class="chart-line" points="<?=e(implode(' ',$points))?>"/><text x="40" y="220"><?=e(substr($trend[0]['created_at'],0,10))?></text><text x="595" y="220"><?=e(substr(end($trend)['created_at'],0,10))?></text></svg><?php }else{?><div class="chart-placeholder"><p>Run at least two audits to see your website’s SEO health trend.</p></div><?php }?><div class="row between small"><span>● <em>SEO health score</em></span><span>Based on saved audit results</span></div></div><div class="card"><div class="card-header"><h3>Your website’s health</h3><span class="small">ⓘ</span></div><div class="score-ring"><svg viewBox="0 0 160 160" aria-hidden="true"><circle cx="80" cy="80" r="65"/><circle class="ring-value" cx="80" cy="80" r="65" stroke-dasharray="<?=($audit['score']??0)*4.084?> 408.4"/></svg><strong><?=e($audit['score']??'—')?><small><?=$audit?'out of 100':'Awaiting first audit'?></small></strong></div><?php foreach(['technical'=>'Technical SEO','onpage'=>'On-page SEO','content'=>'Content quality'] as $key=>$label):?><div class="score-row"><span><?=e($label)?></span><strong><?=e($audit[$key]??'—')?></strong></div><div class="progress"><progress max="100" value="<?=e($audit[$key]??0)?>" aria-label="<?=e($label)?>"></progress></div><?php endforeach;?><p class="small">SEO Health Score is an internal diagnostic score.</p></div></div>
<div class="dashboard-grid"><div class="card"><div class="card-header"><h3>Your next priorities</h3><a class="small" href="<?=url('/tasks?website_id='.$wid)?>">View all tasks →</a></div><?php $tasks=$wid?rows('SELECT title,priority,status,due_date FROM seo_tasks WHERE website_id=? ORDER BY status="completed",id DESC LIMIT 5',[$wid]):[];table(['title'=>'Task','priority'=>'Priority','status'=>'Status','due_date'=>'Due date'],$tasks);?></div><div class="card"><div class="card-header"><h3>Search visibility</h3><span>↗</span></div><?php if((!cfg('RANKING_ENDPOINT')||!cfg('RANKING_API_KEY'))):?><div class="empty"><span class="empty-icon">↗</span><h3>Connect your ranking data</h3><p>Ranking API not configured. Import verified positions or connect a provider to track visibility.</p></div><?php else: $dist=rows('SELECT CASE WHEN position IS NULL THEN "Not found" WHEN position<=3 THEN "Top 3" WHEN position<=10 THEN "Top 10" ELSE "Beyond top 10" END AS label,COUNT(*) AS count FROM keyword_rankings r JOIN keywords k ON k.id=r.keyword_id WHERE k.website_id=? AND r.date=CURDATE() GROUP BY label',[$wid]);table(['label'=>'Position','count'=>'Keywords'],$dist);endif;?></div></div>
<div class="card stack"><div class="card-header"><h3>Make your next move</h3><span class="small">QUICK ACTIONS</span></div><div class="quick-actions"><?php foreach(['websites'=>['◎','Add a website'],'keywords'=>['⌘','Add keywords'],'reports'=>['▥','Create a report'],'rankings'=>['↗','Check Google rankings']] as $path=>[$icon,$label]):?><a class="quick-action" href="<?=url('/'.$path.'?website_id='.$wid)?>"><span><?=e($icon)?></span><?=e($label)?> <small>↗</small></a><?php endforeach;?></div></div>
